import Foundation

// Function to merge two strings
func mergeStrings(_ str1: String, _ str2: String) -> String {

    let array1 = Array(str1)
    let array2 = Array(str2)

    var result: String = ""

    for i in 0..<max(array1.count, array2.count) {
        if i < array1.count {
            result.append(array1[i])
        }
        if i < array2.count {
            result.append(array2[i])
        }
