// Function to compute the aggregate of numerical value of individual digit pairs
int processDigits(char *digits, int len) {
    int sum = 0;
    for(int i = 0; i < len; i += 2) {
        if(i + 1 < len)
            sum += pow((digits[i] - '0'), (digits[i+1] - '0'));
        else
            sum += digits[i] - '0';
    }
    return sum;
}

int main() {
    char digits[1000];
