```java
import java.util.*;
import java.lang.*;

class Solution {
    public List<List<Integer>> pairsSumToZero(int[] l) {
        List<List<Integer>> result = new ArrayList<>();
        HashMap<Integer, Integer> hashMap = new HashMap<>();

        for (int num : l) {
            if (hashMap.containsKey(-num)) {
                result.add(Arrays.asList(-num, num));
            } else {
                hashMap.put(num, -num);
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Solution sol = new Solution();

        //assert statement
        assert sol.pairsSumToZero(new int[] {-1, 1, 2, -2}).equals(Arrays.asList(Arrays.asList(-1, 1), Arrays.asList(2, -2))) : "Test case 1 failed";
        assert sol.pairsSumToZero(new int[] {3, -3, 2, -1, -2, 1}).equals(Arrays.asList(Arrays.asList(-3, 3), Arrays.asList(2, -2), Arrays.asList(-1, 1))) : "Test case 2 failed";
        assert sol.pairsSumToZero(new int[] {0, 0, 0}).equals(Arrays.asList(Arrays.asList(0, 0))) : "Test case 3 failed";
        assert sol.pairsSumToZero(new int[] {1, 3, 2, -4}).equals(new ArrayList<>()) : "Test case 4 failed";
    }
}
