            int currentMax = Math.max(validNumbers.get(i), rollingMinMax.get(rollingMinMax.size()-1).getKey());
            int currentMin = Math.min(validNumbers.get(i), rollingMinMax.get(rollingMinMax.size()-1).getValue());
            if(currentMax != rollingMinMax.get(rollingMinMax.size()-1).getKey()
            || currentMin != rollingMinMax.get(rollingMinMax.size()-1).getValue()) {
                rollingMinMax.add(new AbstractMap.SimpleEntry<>(currentMax, currentMin));
            }
        }

        return rollingMinMax;
    }

