import java.util.List;

public class MeanAndMadCalculator {

    public static double mean(List<Double> inputNumbers) {
        double sum = 0.0;

        for (Double num : inputNumbers) {
            sum += num;
        }

        return sum / inputNumbers.size();
    }

    public static double meanAbsoluteDeviation(List<Double> inputNumbers, double mean) {
        double sumOfDeviations = 0.0;

        for (Double num : inputNumbers) {
            sumOfDeviations += Math.abs(num - mean);
        }

        return sumOfDeviations / inputNumbers.size();
    }

