        List<Double> numbers = Arrays.asList(1.0, 2.0, 3.0, 4.0);
        double mean = mean(numbers);
        double mad = meanAbsoluteDeviation(numbers, mean);

        System.out.println("Mean: " + mean);
        System.out.println("Mean Absolute Deviation: " + mad);
    }
}
```

