Sure, here is the code that implements a binary search algorithm in JavaScript with incorporating error handling for the given scenarios.

```JavaScript
function binarySearch(arr, query) {
  // Check if the array is sorted
  if (!Array.isArray(arr) || arr.some((val, i, arr) => i > 0 && val < arr[i - 1])) {
    throw new Error('Input array is not sorted');
  }
  // Check if the query is a number
  if (typeof query !== 'number') {
    throw new Error('The query must be a number');
  }

  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    let mid = Math.floor((left + right) / 2);

    if (arr[mid] === query) {
      return mid;
    } else if (arr[mid] < query) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return -1;
}

function handleQueries(arr, queries) {
  queries.forEach(query => {
    try {
      let result = binarySearch(arr, query);
      console.log(result !== -1 ? `Element ${query} found at index ${result}` : `Element ${query} not found`);
    } catch (e) {
      console.error(e.message);
    }
  });
}

