use List::Util qw(sum);
use POSIX qw(floor);

sub median_and_standard_deviation {
    my @l = sort { $a <=> $b } @_;
    my $n = scalar @l;
    my $median = 0;
    if ($n % 2 == 0) {
        $median = ($l[floor($n/2)] + $l[floor($n/2) - 1]) / 2.0;
    } else {
        $median = $l[floor($n/2)];
    }

    my $mean = sum(@l) / $n;
    my $variance = sum(map { ($_ - $mean) ** 2 } @l) / $n;
