function filterAndSortChars(text) {
    // Remove all vowels, digits, special characters, and whitespace characters, while ignoring case.
    const consonants = text.toLowerCase().match(/[bcdfghjklmnpqrstvwxyz]/g);

    if(consonants === null) return ""; // Avoid null error in next step

    // Count the occurrences of each element.
    const count = consonants.reduce(function (acc, curr) {
        if (typeof acc[curr] == 'undefined') {
            acc[curr] = 1;
        } else {
            acc[curr] += 1;
        }
        return acc;
    }, {});

    // Sort by frequency.
    const sortedCount = Object.keys(count).sort((a, b) => count[a] - count[b]);

    let result = '';

    // Convert the sorted results back into a string.
    sortedCount.forEach(function (k) {
        result += k.repeat(count[k]);
    });

    return result;
}
```
