This function checks whether a two-digit number meets the following criteria:

1. The sum of the digits is a prime number
2. The number itself is divisible by both digits.

Linking to these criteria, here is how it is translated:

```go
package main

import (
	"errors"
	"fmt"
	"math"
	"strconv"
)

func isComposed(n int) (bool, error) {
	if n < 10 || n > 99 {
		return false, errors.New("The input value must be a two-digit number")
	}

	isPrime := func(n int) bool {
		if n < 2 {
			return false
		}
		sq := int(math.Sqrt(float64(n)))
		for i := 2; i <= sq; i++ {
			if n%i == 0 {
				return false
			}
		}
		return true
	}

	strN := strconv.Itoa(n)
	firstDigit, _ := strconv.Atoi(string(strN[0]))
	secondDigit, _ := strconv.Atoi(string(strN[1]))
	sumOfDigits := firstDigit + secondDigit

	if !isPrime(sumOfDigits) {
		return false, nil
	}
	if n%firstDigit != 0 || n%secondDigit != 0 {
		return false, nil
	}

	return true, nil
}

func main() {
	fmt.Println(isComposed(14))
}
```
