```go
package main

import (
	"strings"
	"unicode"
)

func CompareWordSets(phrase1 string, phrase2 string, specialSymbols []string) bool {
	cleanWord := func(word string) string {
		for {
			r, size := utf8.DecodeRuneInString(word)
			if !unicode.IsPunct(r) && !strings.Contains(strings.Join(specialSymbols, ""), string(r)) {
				break
			}
			word = word[size:]
		}

		for {
			r, size := utf8.DecodeLastRuneInString(word)
			if !unicode.IsPunct(r) && !strings.Contains(strings.Join(specialSymbols, ""), string(r)) {
				break
			}
			word = word[:len(word)-size]
		}
		return word
	}

	toWordsSet := func(phrase string) map[string]bool {
		words := map[string]bool{}
		for _, word := range strings.Fields(strings.ToLower(phrase)) {
			word = cleanWord(word)
			words[word] = true
		}
		return words
	}

	words1 := toWordsSet(phrase1)
	words2 := toWordsSet(phrase2)

	if len(words1) != len(words2) {
		return false
	}

	for word := range words1 {
		if !words2[word] {
			return false
		}
	}

	return true
}
```
